SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.careunit, COUNT(DISTINCT a.subject_id) AS patient_count, AVG(a.los) AS avg_los FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.stay_id = i.stay_id WHERE p.gender = 'M' AND p.anchor_age = 53 AND p.anchor_year = 2017 AND p.anchor_year_group = '53-58' AND i.careunit IS NOT NULL AND i.careunit != '' AND a.admission_type = 'Ultrasound' AND a.discharge_location = 'ICU' AND i.intime <= a.admittime AND i.outtime >= a.discharge_location AND (a.discharge_location - a.admittime) <= 8 AND (a.discharge_location - a.admittime) >= 1 GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.careunit ORDER BY patient_count DESC NULLS LAST;